    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Each contiguous nonzero boundary run is a sequence template. Isolated
    # occurrences of one of its values are expanded to that complete run,
    # aligned so that the matching value stays in its original cell.
    templates = []
    for row in (grid[0], grid[-1]):
        run = []
        for value in row:
            if value:
                run.append(value)
            elif run:
                templates.append(run)
                run = []
        if run:
            templates.append(run)

    for r in range(1, h - 1):
        for c, value in enumerate(grid[r]):
            if value == 0:
                continue
            template = next((seq for seq in templates if value in seq), None)
            if template is None:
                continue
            start = c - template.index(value)
            for i, item in enumerate(template):
                if 0 <= start + i < w:
                    out[r][start + i] = item
    return out
